(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit22-trap-c4-basic-1"]={"id":"unit22-trap-c4-basic-1","unitId":"2-2","chapterIds":["2-2"],"unitType":"basic","group":"2-2단원 · 선지 변형 유형 · 비교","name":"기본 OX 1","level":"기본","revision":3,"resetReviewOnRevision":true,"originPage":"unit22","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"비교","parts":[{"name":"U22-20-B1 · 비교","items":[{"paragraphCount":1,"readingLabel":"6문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 6문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 6문단]\n이렇게 시장 거래의 결과로 구매자와 판매자는 모두 행복해지고 효용은 증가한다. 이것이 바로 자유 시장이 재화를 효율적으로 분배한다고 주장하는 경제학자들의 입장이다. 시장은 사람들이 상호 유리한 방향으로 거래하는 것을 허용함으로써, 재화에 가장 높은 가치를 매기는 사람에게 그 재화를 할당한다. 그리고 그 기준은 얼마나 지불할 의사가 있느냐로 측정한다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"originPage":"unit22","skills":["비교"],"id":"U22-20-B1","type":"ox","highlightEvidence":true,"ask":"다음 설명이 지문과 같으면 O, 다르면 X를 고르세요.","changed":"시장을 지지하는 사람들은 물건을 사려고 얼마까지 낼 생각인지 살핀다. 더 많은 돈을 내겠다는 사람이 물건을 더 소중히 여긴다고 본다.","answer":"O","why":"시장을 지지하는 사람들은 물건을 얼마나 원하는지 돈으로 판단해요. 얼마까지 낼 생각인지가 판단 기준이에요.\n6문단에서 확인할 수 있어요.","evidence":{"title":"가치 평가와 지불 의사","statement":"시장을 지지하는 사람들은 물건을 사려고 얼마까지 낼 생각인지 살핀다. 더 많은 돈을 내겠다는 사람이 물건을 더 소중히 여긴다고 본다.","explanation":"시장을 지지하는 사람들은 물건을 얼마나 원하는지 돈으로 판단해요. 얼마까지 낼 생각인지가 판단 기준이에요.\n6문단에서 확인할 수 있어요.","valid":["L06:4"],"sources":[{"id":"L06","title":"줄 서기를 돈으로 살 수 있을까","label":"6문단","sentences":[{"id":"L06:1","text":"이렇게 시장 거래의 결과로 구매자와 판매자는 모두 행복해지고 효용은 증가한다.","paragraph":0,"memberIds":["L06:1"],"topic":"정리하면, 거래 덕분에 사는 사람도 파는 사람도 행복해지고 만족(효용)이 커진다."},{"id":"L06:2","text":"이것이 바로 자유 시장이 재화를 효율적으로 분배한다고 주장하는 경제학자들의 입장이다.","paragraph":0,"memberIds":["L06:2"],"topic":"그래서 경제학자들은 \"시장에 맡기면 물건(재화)이 낭비 없이 가장 알맞게(효율적으로) 나뉜다.\"라고 말한다."},{"id":"L06:3","text":"시장은 사람들이 상호 유리한 방향으로 거래하는 것을 허용함으로써, 재화에 가장 높은 가치를 매기는 사람에게 그 재화를 할당한다.","paragraph":0,"memberIds":["L06:3"],"topic":"시장에서는 서로 이득이 되는 거래를 자유롭게 할 수 있다. 그러면 물건은 그 물건을 가장 귀하게 여기는 사람에게 간다."},{"id":"L06:4","text":"그리고 그 기준은 얼마나 지불할 의사가 있느냐로 측정한다.","paragraph":0,"memberIds":["L06:4"],"topic":"그런데 '누가 가장 귀하게 여기는지'는 '누가 돈을 가장 많이 낼 마음이 있는지'로 잰다."}]}]},"editorSourceVersion":"508cfdfa65b2c6c23f23598f02dd9f50458c600f64c92949c36f0c2b605b3166"}]},{"name":"U22-20-B2 · 비교","items":[{"paragraphCount":1,"readingLabel":"6문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 6문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 6문단]\n이렇게 시장 거래의 결과로 구매자와 판매자는 모두 행복해지고 효용은 증가한다. 이것이 바로 자유 시장이 재화를 효율적으로 분배한다고 주장하는 경제학자들의 입장이다. 시장은 사람들이 상호 유리한 방향으로 거래하는 것을 허용함으로써, 재화에 가장 높은 가치를 매기는 사람에게 그 재화를 할당한다. 그리고 그 기준은 얼마나 지불할 의사가 있느냐로 측정한다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"originPage":"unit22","skills":["비교"],"id":"U22-20-B2","type":"ox","highlightEvidence":true,"ask":"다음 설명이 지문과 같으면 O, 다르면 X를 고르세요.","changed":"시장을 지지하는 사람들은 물건을 팔지 않으려는 마음으로 물건을 얼마나 소중히 여기는지 판단한다.","answer":"X","why":"시장을 지지하는 사람들은 물건에 돈을 내려는 마음으로 물건을 얼마나 소중히 여기는지 판단한다.\n시장을 지지하는 사람들은 물건을 얼마나 원하는지 돈으로 판단해요. 얼마까지 낼 생각인지가 판단 기준이에요.\n6문단에서 확인할 수 있어요.","claimEdits":[{"start":14,"end":26,"before":"물건을 팔지 않으려는 ","after":"물건에 돈을 내려는 "}],"evidence":{"title":"가치 평가와 지불 의사","statement":"시장을 지지하는 사람들은 물건을 사려고 얼마까지 낼 생각인지 살핀다. 더 많은 돈을 내겠다는 사람이 물건을 더 소중히 여긴다고 본다.","explanation":"시장을 지지하는 사람들은 물건을 얼마나 원하는지 돈으로 판단해요. 얼마까지 낼 생각인지가 판단 기준이에요.\n6문단에서 확인할 수 있어요.","valid":["L06:4"],"sources":[{"id":"L06","title":"줄 서기를 돈으로 살 수 있을까","label":"6문단","sentences":[{"id":"L06:1","text":"이렇게 시장 거래의 결과로 구매자와 판매자는 모두 행복해지고 효용은 증가한다.","paragraph":0,"memberIds":["L06:1"],"topic":"정리하면, 거래 덕분에 사는 사람도 파는 사람도 행복해지고 만족(효용)이 커진다."},{"id":"L06:2","text":"이것이 바로 자유 시장이 재화를 효율적으로 분배한다고 주장하는 경제학자들의 입장이다.","paragraph":0,"memberIds":["L06:2"],"topic":"그래서 경제학자들은 \"시장에 맡기면 물건(재화)이 낭비 없이 가장 알맞게(효율적으로) 나뉜다.\"라고 말한다."},{"id":"L06:3","text":"시장은 사람들이 상호 유리한 방향으로 거래하는 것을 허용함으로써, 재화에 가장 높은 가치를 매기는 사람에게 그 재화를 할당한다.","paragraph":0,"memberIds":["L06:3"],"topic":"시장에서는 서로 이득이 되는 거래를 자유롭게 할 수 있다. 그러면 물건은 그 물건을 가장 귀하게 여기는 사람에게 간다."},{"id":"L06:4","text":"그리고 그 기준은 얼마나 지불할 의사가 있느냐로 측정한다.","paragraph":0,"memberIds":["L06:4"],"topic":"그런데 '누가 가장 귀하게 여기는지'는 '누가 돈을 가장 많이 낼 마음이 있는지'로 잰다."}]}]},"editorSourceVersion":"005b03fe153b83c076de01fc93a6cd7e4b7f289a3c3f67057c69d1818f773375"}]},{"name":"U22-31-B1 · 비교","items":[{"paragraphCount":1,"readingLabel":"12문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 12문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 12문단]\n하지만 이러한 주장은 설득력이 없다. 우리의 목적이 사회적 효용을 극대화하는 것이라 할지라도, 자유 시장이 줄 서기보다 믿음직스럽지 않을 수도 있다. 어떤 재화에 기꺼이 가격을 지불하려는 것이 꼭 해당 재화의 가치를 높게 평가한다는 뜻은 아니기 때문이다. 시장 가격에는 자발적으로 지불하려는 마음만큼이나 지불할 수 있는 능력도 반영된다. 셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다. 그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"originPage":"unit22","skills":["비교"],"id":"U22-31-B1","type":"ox","highlightEvidence":true,"ask":"다음 설명이 지문과 같으면 O, 다르면 X를 고르세요.","changed":"가격에는 돈을 얼마나 내고 싶은지가 드러난다. 글쓴이는 실제로 얼마나 낼 수 있는지도 가격에 드러난다고 본다.","answer":"O","why":"돈을 내고 싶은 마음과 실제로 낼 수 있는 돈은 달라요. 공연을 매우 좋아해도 가진 돈이 적으면 비싼 값을 낼 수 없어요.\n12문단에서 확인할 수 있어요.","evidence":{"title":"시장 가격을 구성하는 두 요인","statement":"가격에는 돈을 얼마나 내고 싶은지가 드러난다. 글쓴이는 실제로 얼마나 낼 수 있는지도 가격에 드러난다고 본다.","explanation":"돈을 내고 싶은 마음과 실제로 낼 수 있는 돈은 달라요. 공연을 매우 좋아해도 가진 돈이 적으면 비싼 값을 낼 수 없어요.\n12문단에서 확인할 수 있어요.","valid":["L12:4"],"sources":[{"id":"L12","title":"줄 서기를 돈으로 살 수 있을까","label":"12문단","sentences":[{"id":"L12:1","text":"하지만 이러한 주장은 설득력이 없다.","paragraph":0,"memberIds":["L12:1"],"topic":"필자는 11문단에서 예상한 시장 옹호자의 반론, 곧 “비싼 값을 내는 사람이 공연을 가장 원하므로 시장에 맡기자”는 주장에 설득력이 없다고 본다."},{"id":"L12:2","text":"우리의 목적이 사회적 효용을 극대화하는 것이라 할지라도, 자유 시장이 줄 서기보다 믿음직스럽지 않을 수도 있다.","paragraph":0,"memberIds":["L12:2"],"topic":"목표가 '모두의 만족을 최대로'라고 쳐도, 시장이 줄 서기보다 더 믿을 만하지 않을 수도 있다."},{"id":"L12:3","text":"어떤 재화에 기꺼이 가격을 지불하려는 것이 꼭 해당 재화의 가치를 높게 평가한다는 뜻은 아니기 때문이다.","paragraph":0,"memberIds":["L12:3"],"topic":"돈을 많이 낸다고 해서 꼭 그걸 더 좋아한다는 뜻은 아니기 때문이다."},{"id":"L12:4","text":"시장 가격에는 자발적으로 지불하려는 마음만큼이나 지불할 수 있는 능력도 반영된다.","paragraph":0,"memberIds":["L12:4"],"topic":"가격에는 '얼마나 사고 싶은지(마음)'뿐 아니라 '돈이 얼마나 있는지(능력)'도 들어 있다."},{"id":"L12:5","text":"셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다.","paragraph":0,"memberIds":["L12:5"],"topic":"공연이나 경기를 가장 보고 싶은 사람도 표 살 돈이 없을 수 있다."},{"id":"L12:6","text":"그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.","paragraph":0,"memberIds":["L12:6"],"topic":"반대로, 가장 비싼 표를 산 사람이 그 공연을 별로 좋아하지 않을 수도 있다."}]}]},"editorSourceVersion":"73a13fea20dd396d044e2388b7e30075029f81a0bf1a76d4909d9a4d0c816447"}]},{"name":"U22-31-B2 · 비교","items":[{"paragraphCount":1,"readingLabel":"12문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 12문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 12문단]\n하지만 이러한 주장은 설득력이 없다. 우리의 목적이 사회적 효용을 극대화하는 것이라 할지라도, 자유 시장이 줄 서기보다 믿음직스럽지 않을 수도 있다. 어떤 재화에 기꺼이 가격을 지불하려는 것이 꼭 해당 재화의 가치를 높게 평가한다는 뜻은 아니기 때문이다. 시장 가격에는 자발적으로 지불하려는 마음만큼이나 지불할 수 있는 능력도 반영된다. 셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다. 그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"originPage":"unit22","skills":["비교"],"id":"U22-31-B2","type":"ox","highlightEvidence":true,"ask":"다음 설명이 지문과 같으면 O, 다르면 X를 고르세요.","changed":"가격은 돈을 내고 싶은 마음과 판매자의 수입으로만 정해진다고 본다.","answer":"X","why":"가격은 돈을 내고 싶은 마음과 실제로 낼 수 있는 돈에 따라 달라진다고 본다.\n돈을 내고 싶은 마음과 실제로 낼 수 있는 돈은 달라요. 공연을 매우 좋아해도 가진 돈이 적으면 비싼 값을 낼 수 없어요.\n12문단에서 확인할 수 있어요.","claimEdits":[{"start":17,"end":34,"before":"판매자의 수입으로만 정해진다고 ","after":"실제로 낼 수 있는 돈에 따라 달라진다고 "}],"evidence":{"title":"시장 가격을 구성하는 두 요인","statement":"가격에는 돈을 얼마나 내고 싶은지가 드러난다. 글쓴이는 실제로 얼마나 낼 수 있는지도 가격에 드러난다고 본다.","explanation":"돈을 내고 싶은 마음과 실제로 낼 수 있는 돈은 달라요. 공연을 매우 좋아해도 가진 돈이 적으면 비싼 값을 낼 수 없어요.\n12문단에서 확인할 수 있어요.","valid":["L12:4"],"sources":[{"id":"L12","title":"줄 서기를 돈으로 살 수 있을까","label":"12문단","sentences":[{"id":"L12:1","text":"하지만 이러한 주장은 설득력이 없다.","paragraph":0,"memberIds":["L12:1"],"topic":"필자는 11문단에서 예상한 시장 옹호자의 반론, 곧 “비싼 값을 내는 사람이 공연을 가장 원하므로 시장에 맡기자”는 주장에 설득력이 없다고 본다."},{"id":"L12:2","text":"우리의 목적이 사회적 효용을 극대화하는 것이라 할지라도, 자유 시장이 줄 서기보다 믿음직스럽지 않을 수도 있다.","paragraph":0,"memberIds":["L12:2"],"topic":"목표가 '모두의 만족을 최대로'라고 쳐도, 시장이 줄 서기보다 더 믿을 만하지 않을 수도 있다."},{"id":"L12:3","text":"어떤 재화에 기꺼이 가격을 지불하려는 것이 꼭 해당 재화의 가치를 높게 평가한다는 뜻은 아니기 때문이다.","paragraph":0,"memberIds":["L12:3"],"topic":"돈을 많이 낸다고 해서 꼭 그걸 더 좋아한다는 뜻은 아니기 때문이다."},{"id":"L12:4","text":"시장 가격에는 자발적으로 지불하려는 마음만큼이나 지불할 수 있는 능력도 반영된다.","paragraph":0,"memberIds":["L12:4"],"topic":"가격에는 '얼마나 사고 싶은지(마음)'뿐 아니라 '돈이 얼마나 있는지(능력)'도 들어 있다."},{"id":"L12:5","text":"셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다.","paragraph":0,"memberIds":["L12:5"],"topic":"공연이나 경기를 가장 보고 싶은 사람도 표 살 돈이 없을 수 있다."},{"id":"L12:6","text":"그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.","paragraph":0,"memberIds":["L12:6"],"topic":"반대로, 가장 비싼 표를 산 사람이 그 공연을 별로 좋아하지 않을 수도 있다."}]}]},"editorSourceVersion":"35a75626164a077fa45330a1f93f958f70b61d3e285ee6763bf228755b06acdc"}]},{"name":"U22-35-B1 · 비교","items":[{"paragraphCount":1,"readingLabel":"14문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 14문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 14문단]\n암표 거래를 옹호하는 사람들은 줄 서기가 시간이 남아도는 사람들에게 유리한 차별이라고 비판한다. 맞는 말이지만, 시장이 돈 많은 사람들을 유리하게 차별한다는 말과 같은 맥락에서만 그러하다. 시장이 자발적으로 돈을 지불하려는 마음과 능력을 바탕으로 재화를 분배하듯, 줄 서기는 자발적으로 기다리려는 마음과 능력을 바탕으로 재화를 분배한다. 그리고 자발적으로 가격을 지불하려는 마음이, 자발적으로 줄을 서서 기다리려는 마음보다 더 나은 가치 평가 기준이라고 추정할 근거는 없다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"originPage":"unit22","skills":["비교"],"id":"U22-35-B1","type":"ox","highlightEvidence":true,"ask":"다음 설명이 지문과 같으면 O, 다르면 X를 고르세요.","changed":"줄을 세우면 시간 많은 사람이 유리하다. 돈을 받고 팔면 돈 많은 사람이 유리하다. 글쓴이는 두 방법에 이런 문제가 있음을 인정한다.","answer":"O","why":"첫 문장은 암표 거래 옹호자의 비판입니다. “맞는 말이지만”부터는 필자의 평가예요. 필자는 줄 서기가 시간 많은 사람에게 유리하다는 점은 인정하면서, 시장도 돈 많은 사람에게 유리하다고 덧붙여요.\n14문단에서 확인할 수 있어요.","evidence":{"title":"시간 차별 비판을 인정하는 범위","statement":"줄을 세우면 시간 많은 사람이 유리하다. 돈을 받고 팔면 돈 많은 사람이 유리하다. 글쓴이는 두 방법에 이런 문제가 있음을 인정한다.","explanation":"첫 문장은 암표 거래 옹호자의 비판입니다. “맞는 말이지만”부터는 필자의 평가예요. 필자는 줄 서기가 시간 많은 사람에게 유리하다는 점은 인정하면서, 시장도 돈 많은 사람에게 유리하다고 덧붙여요.\n14문단에서 확인할 수 있어요.","valid":["L14:2"],"sources":[{"id":"L14","title":"줄 서기를 돈으로 살 수 있을까","label":"14문단","sentences":[{"id":"L14:1","text":"암표 거래를 옹호하는 사람들은 줄 서기가 시간이 남아도는 사람들에게 유리한 차별이라고 비판한다.","paragraph":0,"memberIds":["L14:1"],"topic":"암표 거래를 옹호하는 사람들은 “줄 서기도 시간이 많은 사람에게 유리한 차별이다”라고 비판한다."},{"id":"L14:2","text":"맞는 말이지만, 시장이 돈 많은 사람들을 유리하게 차별한다는 말과 같은 맥락에서만 그러하다.","paragraph":0,"memberIds":["L14:2"],"topic":"필자는 그 지적을 인정한다. 다만 시장도 돈 많은 사람에게 유리하므로, 줄 서기에만 있는 문제는 아니라고 말한다."},{"id":"L14:3","text":"시장이 자발적으로 돈을 지불하려는 마음과 능력을 바탕으로 재화를 분배하듯, 줄 서기는 자발적으로 기다리려는 마음과 능력을 바탕으로 재화를 분배한다.","paragraph":0,"memberIds":["L14:3"],"topic":"시장은 '돈 낼 마음 + 돈'으로 나눈다. 줄 서기는 '기다릴 마음 + 시간'으로 나눈다."},{"id":"L14:4","text":"그리고 자발적으로 가격을 지불하려는 마음이, 자발적으로 줄을 서서 기다리려는 마음보다 더 나은 가치 평가 기준이라고 추정할 근거는 없다.","paragraph":0,"memberIds":["L14:4"],"topic":"그리고 '돈을 내겠다는 마음'이 '기다리겠다는 마음'보다 더 좋은 기준이라고 볼 이유는 없다."}]}]},"editorSourceVersion":"d9177049504ee06e21b3f6b54b2381df2fc1b993b3dd356e3c1449f4ca6efb5d"}]},{"name":"U22-35-B2 · 비교","items":[{"paragraphCount":1,"readingLabel":"14문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 14문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 14문단]\n암표 거래를 옹호하는 사람들은 줄 서기가 시간이 남아도는 사람들에게 유리한 차별이라고 비판한다. 맞는 말이지만, 시장이 돈 많은 사람들을 유리하게 차별한다는 말과 같은 맥락에서만 그러하다. 시장이 자발적으로 돈을 지불하려는 마음과 능력을 바탕으로 재화를 분배하듯, 줄 서기는 자발적으로 기다리려는 마음과 능력을 바탕으로 재화를 분배한다. 그리고 자발적으로 가격을 지불하려는 마음이, 자발적으로 줄을 서서 기다리려는 마음보다 더 나은 가치 평가 기준이라고 추정할 근거는 없다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"originPage":"unit22","skills":["비교"],"id":"U22-35-B2","type":"ox","highlightEvidence":true,"ask":"다음 설명이 지문과 같으면 O, 다르면 X를 고르세요.","changed":"글쓴이는 줄 서기가 시간 많은 사람에게 유리하다는 말을 부정한다.","answer":"X","why":"글쓴이는 줄 서기가 시간 많은 사람에게 유리하다는 말을 인정한다.\n첫 문장은 암표 거래 옹호자의 비판입니다. “맞는 말이지만”부터는 필자의 평가예요. 필자는 줄 서기가 시간 많은 사람에게 유리하다는 점은 인정하면서, 시장도 돈 많은 사람에게 유리하다고 덧붙여요.\n14문단에서 확인할 수 있어요.","claimEdits":[{"start":31,"end":36,"before":"부정한다.","after":"인정한다."}],"evidence":{"title":"시간 차별 비판을 인정하는 범위","statement":"줄을 세우면 시간 많은 사람이 유리하다. 돈을 받고 팔면 돈 많은 사람이 유리하다. 글쓴이는 두 방법에 이런 문제가 있음을 인정한다.","explanation":"첫 문장은 암표 거래 옹호자의 비판입니다. “맞는 말이지만”부터는 필자의 평가예요. 필자는 줄 서기가 시간 많은 사람에게 유리하다는 점은 인정하면서, 시장도 돈 많은 사람에게 유리하다고 덧붙여요.\n14문단에서 확인할 수 있어요.","valid":["L14:2"],"sources":[{"id":"L14","title":"줄 서기를 돈으로 살 수 있을까","label":"14문단","sentences":[{"id":"L14:1","text":"암표 거래를 옹호하는 사람들은 줄 서기가 시간이 남아도는 사람들에게 유리한 차별이라고 비판한다.","paragraph":0,"memberIds":["L14:1"],"topic":"암표 거래를 옹호하는 사람들은 “줄 서기도 시간이 많은 사람에게 유리한 차별이다”라고 비판한다."},{"id":"L14:2","text":"맞는 말이지만, 시장이 돈 많은 사람들을 유리하게 차별한다는 말과 같은 맥락에서만 그러하다.","paragraph":0,"memberIds":["L14:2"],"topic":"필자는 그 지적을 인정한다. 다만 시장도 돈 많은 사람에게 유리하므로, 줄 서기에만 있는 문제는 아니라고 말한다."},{"id":"L14:3","text":"시장이 자발적으로 돈을 지불하려는 마음과 능력을 바탕으로 재화를 분배하듯, 줄 서기는 자발적으로 기다리려는 마음과 능력을 바탕으로 재화를 분배한다.","paragraph":0,"memberIds":["L14:3"],"topic":"시장은 '돈 낼 마음 + 돈'으로 나눈다. 줄 서기는 '기다릴 마음 + 시간'으로 나눈다."},{"id":"L14:4","text":"그리고 자발적으로 가격을 지불하려는 마음이, 자발적으로 줄을 서서 기다리려는 마음보다 더 나은 가치 평가 기준이라고 추정할 근거는 없다.","paragraph":0,"memberIds":["L14:4"],"topic":"그리고 '돈을 내겠다는 마음'이 '기다리겠다는 마음'보다 더 좋은 기준이라고 볼 이유는 없다."}]}]},"editorSourceVersion":"4077759d434db9beba5ad4b35da1464f66c00a7d92929bc99e1dd1ca3a817264"}]},{"name":"U22-36-B1 · 비교","items":[{"paragraphCount":1,"readingLabel":"14문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 14문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 14문단]\n암표 거래를 옹호하는 사람들은 줄 서기가 시간이 남아도는 사람들에게 유리한 차별이라고 비판한다. 맞는 말이지만, 시장이 돈 많은 사람들을 유리하게 차별한다는 말과 같은 맥락에서만 그러하다. 시장이 자발적으로 돈을 지불하려는 마음과 능력을 바탕으로 재화를 분배하듯, 줄 서기는 자발적으로 기다리려는 마음과 능력을 바탕으로 재화를 분배한다. 그리고 자발적으로 가격을 지불하려는 마음이, 자발적으로 줄을 서서 기다리려는 마음보다 더 나은 가치 평가 기준이라고 추정할 근거는 없다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"originPage":"unit22","skills":["비교"],"id":"U22-36-B1","type":"ox","highlightEvidence":true,"ask":"다음 설명이 지문과 같으면 O, 다르면 X를 고르세요.","changed":"돈을 받고 팔 때는 돈을 내려는 마음과 낼 수 있는 돈이 중요하다. 줄을 세울 때는 기다리려는 마음과 기다릴 수 있는 시간이 중요하다. 돈을 낼 마음이 기다릴 마음보다 간절함을 더 잘 보여 준다는 근거는 없다.","answer":"O","why":"돈을 내려는 마음이 있어도 돈이 부족할 수 있고, 기다리고 싶어도 시간이 없을 수 있어요. 돈을 내려는 마음이 기다리려는 마음보다 더 정확한 판단 기준이라고 할 이유는 없어요.\n14문단에서 확인할 수 있어요.","evidence":{"title":"돈과 시간의 대칭적 비교","statement":"돈을 받고 팔 때는 돈을 내려는 마음과 낼 수 있는 돈이 중요하다. 줄을 세울 때는 기다리려는 마음과 기다릴 수 있는 시간이 중요하다. 돈을 낼 마음이 기다릴 마음보다 간절함을 더 잘 보여 준다는 근거는 없다.","explanation":"돈을 내려는 마음이 있어도 돈이 부족할 수 있고, 기다리고 싶어도 시간이 없을 수 있어요. 돈을 내려는 마음이 기다리려는 마음보다 더 정확한 판단 기준이라고 할 이유는 없어요.\n14문단에서 확인할 수 있어요.","valid":["L14:3","L14:4"],"sources":[{"id":"L14","title":"줄 서기를 돈으로 살 수 있을까","label":"14문단","sentences":[{"id":"L14:1","text":"암표 거래를 옹호하는 사람들은 줄 서기가 시간이 남아도는 사람들에게 유리한 차별이라고 비판한다.","paragraph":0,"memberIds":["L14:1"],"topic":"암표 거래를 옹호하는 사람들은 “줄 서기도 시간이 많은 사람에게 유리한 차별이다”라고 비판한다."},{"id":"L14:2","text":"맞는 말이지만, 시장이 돈 많은 사람들을 유리하게 차별한다는 말과 같은 맥락에서만 그러하다.","paragraph":0,"memberIds":["L14:2"],"topic":"필자는 그 지적을 인정한다. 다만 시장도 돈 많은 사람에게 유리하므로, 줄 서기에만 있는 문제는 아니라고 말한다."},{"id":"L14:3","text":"시장이 자발적으로 돈을 지불하려는 마음과 능력을 바탕으로 재화를 분배하듯, 줄 서기는 자발적으로 기다리려는 마음과 능력을 바탕으로 재화를 분배한다.","paragraph":0,"memberIds":["L14:3"],"topic":"시장은 '돈 낼 마음 + 돈'으로 나눈다. 줄 서기는 '기다릴 마음 + 시간'으로 나눈다."},{"id":"L14:4","text":"그리고 자발적으로 가격을 지불하려는 마음이, 자발적으로 줄을 서서 기다리려는 마음보다 더 나은 가치 평가 기준이라고 추정할 근거는 없다.","paragraph":0,"memberIds":["L14:4"],"topic":"그리고 '돈을 내겠다는 마음'이 '기다리겠다는 마음'보다 더 좋은 기준이라고 볼 이유는 없다."}]}]},"editorSourceVersion":"2d36a873af530bc81d3d4ee9317cdb1bfddf311f68933a66b98c9d7773d7f746"}]},{"name":"U22-36-B2 · 비교","items":[{"paragraphCount":1,"readingLabel":"14문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 14문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 14문단]\n암표 거래를 옹호하는 사람들은 줄 서기가 시간이 남아도는 사람들에게 유리한 차별이라고 비판한다. 맞는 말이지만, 시장이 돈 많은 사람들을 유리하게 차별한다는 말과 같은 맥락에서만 그러하다. 시장이 자발적으로 돈을 지불하려는 마음과 능력을 바탕으로 재화를 분배하듯, 줄 서기는 자발적으로 기다리려는 마음과 능력을 바탕으로 재화를 분배한다. 그리고 자발적으로 가격을 지불하려는 마음이, 자발적으로 줄을 서서 기다리려는 마음보다 더 나은 가치 평가 기준이라고 추정할 근거는 없다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"originPage":"unit22","skills":["비교"],"id":"U22-36-B2","type":"ox","highlightEvidence":true,"ask":"다음 설명이 지문과 같으면 O, 다르면 X를 고르세요.","changed":"돈을 더 내겠다는 마음이 오래 기다리겠다는 마음보다 간절함을 더 잘 보여 준다는 근거가 충분하다.","answer":"X","why":"돈을 더 내겠다는 마음이 오래 기다리겠다는 마음보다 간절함을 더 잘 보여 준다는 근거는 없다.\n돈을 내려는 마음이 있어도 돈이 부족할 수 있고, 기다리고 싶어도 시간이 없을 수 있어요. 돈을 내려는 마음이 기다리려는 마음보다 더 정확한 판단 기준이라고 할 이유는 없어요.\n14문단에서 확인할 수 있어요.","claimEdits":[{"start":45,"end":54,"before":"근거가 충분하다.","after":"근거는 없다."}],"evidence":{"title":"돈과 시간의 대칭적 비교","statement":"돈을 받고 팔 때는 돈을 내려는 마음과 낼 수 있는 돈이 중요하다. 줄을 세울 때는 기다리려는 마음과 기다릴 수 있는 시간이 중요하다. 돈을 낼 마음이 기다릴 마음보다 간절함을 더 잘 보여 준다는 근거는 없다.","explanation":"돈을 내려는 마음이 있어도 돈이 부족할 수 있고, 기다리고 싶어도 시간이 없을 수 있어요. 돈을 내려는 마음이 기다리려는 마음보다 더 정확한 판단 기준이라고 할 이유는 없어요.\n14문단에서 확인할 수 있어요.","valid":["L14:4"],"sources":[{"id":"L14","title":"줄 서기를 돈으로 살 수 있을까","label":"14문단","sentences":[{"id":"L14:1","text":"암표 거래를 옹호하는 사람들은 줄 서기가 시간이 남아도는 사람들에게 유리한 차별이라고 비판한다.","paragraph":0,"memberIds":["L14:1"],"topic":"암표 거래를 옹호하는 사람들은 “줄 서기도 시간이 많은 사람에게 유리한 차별이다”라고 비판한다."},{"id":"L14:2","text":"맞는 말이지만, 시장이 돈 많은 사람들을 유리하게 차별한다는 말과 같은 맥락에서만 그러하다.","paragraph":0,"memberIds":["L14:2"],"topic":"필자는 그 지적을 인정한다. 다만 시장도 돈 많은 사람에게 유리하므로, 줄 서기에만 있는 문제는 아니라고 말한다."},{"id":"L14:3","text":"시장이 자발적으로 돈을 지불하려는 마음과 능력을 바탕으로 재화를 분배하듯, 줄 서기는 자발적으로 기다리려는 마음과 능력을 바탕으로 재화를 분배한다.","paragraph":0,"memberIds":["L14:3"],"topic":"시장은 '돈 낼 마음 + 돈'으로 나눈다. 줄 서기는 '기다릴 마음 + 시간'으로 나눈다."},{"id":"L14:4","text":"그리고 자발적으로 가격을 지불하려는 마음이, 자발적으로 줄을 서서 기다리려는 마음보다 더 나은 가치 평가 기준이라고 추정할 근거는 없다.","paragraph":0,"memberIds":["L14:4"],"topic":"그리고 '돈을 내겠다는 마음'이 '기다리겠다는 마음'보다 더 좋은 기준이라고 볼 이유는 없다."}]}]},"editorSourceVersion":"120d6fcda74c9da730e9822a1adfc1aea00407dbf6961b18885ddc2e04472c44"}]},{"name":"U22-46-B1 · 비교","items":[{"paragraphCount":2,"readingLabel":"14문단 · 새 예시 적용","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 14문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 14문단]\n암표 거래를 옹호하는 사람들은 줄 서기가 시간이 남아도는 사람들에게 유리한 차별이라고 비판한다. 맞는 말이지만, 시장이 돈 많은 사람들을 유리하게 차별한다는 말과 같은 맥락에서만 그러하다. 시장이 자발적으로 돈을 지불하려는 마음과 능력을 바탕으로 재화를 분배하듯, 줄 서기는 자발적으로 기다리려는 마음과 능력을 바탕으로 재화를 분배한다. 그리고 자발적으로 가격을 지불하려는 마음이, 자발적으로 줄을 서서 기다리려는 마음보다 더 나은 가치 평가 기준이라고 추정할 근거는 없다.\n\n[새 적용 예시 · 원문 사례 아님]\n학급에서 유니폼을 나눌 방법으로 최고가 경매와 먼저 와서 기다린 사람에게 주는 선착순을 비교한다. 학생마다 가진 돈과 기다릴 수 있는 시간은 다르다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"originPage":"unit22","skills":["비교"],"id":"U22-46-B1","type":"ox","highlightEvidence":true,"ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","changed":"경매는 돈 많은 사람에게 유리하다. 선착순도 기다릴 시간이 많은 사람에게 유리할 수 있다. 선착순이 완벽한 기준은 아니다.","answer":"O","why":"돈이 많으면 경매에서 높은 값을 부르기 쉬워요. 시간이 많으면 줄을 오래 서기 쉬워요. 경매에 문제가 있다고 해서 선착순에 아무 문제가 없는 것은 아니에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 14문단의 내용과 비교해 보세요.","evidence":{"title":"웹 적용 · 경매와 선착순","statement":"경매는 돈 많은 사람에게 유리하다. 선착순도 기다릴 시간이 많은 사람에게 유리할 수 있다. 선착순이 완벽한 기준은 아니다.","explanation":"돈이 많으면 경매에서 높은 값을 부르기 쉬워요. 시간이 많으면 줄을 오래 서기 쉬워요. 경매에 문제가 있다고 해서 선착순에 아무 문제가 없는 것은 아니에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 14문단의 내용과 비교해 보세요.","valid":["L14:1","L14:2","L14:3","L14:4"],"sources":[{"id":"L14","title":"줄 서기를 돈으로 살 수 있을까","label":"14문단","sentences":[{"id":"L14:1","text":"암표 거래를 옹호하는 사람들은 줄 서기가 시간이 남아도는 사람들에게 유리한 차별이라고 비판한다.","paragraph":0,"memberIds":["L14:1"],"topic":"암표 거래를 옹호하는 사람들은 “줄 서기도 시간이 많은 사람에게 유리한 차별이다”라고 비판한다."},{"id":"L14:2","text":"맞는 말이지만, 시장이 돈 많은 사람들을 유리하게 차별한다는 말과 같은 맥락에서만 그러하다.","paragraph":0,"memberIds":["L14:2"],"topic":"필자는 그 지적을 인정한다. 다만 시장도 돈 많은 사람에게 유리하므로, 줄 서기에만 있는 문제는 아니라고 말한다."},{"id":"L14:3","text":"시장이 자발적으로 돈을 지불하려는 마음과 능력을 바탕으로 재화를 분배하듯, 줄 서기는 자발적으로 기다리려는 마음과 능력을 바탕으로 재화를 분배한다.","paragraph":0,"memberIds":["L14:3"],"topic":"시장은 '돈 낼 마음 + 돈'으로 나눈다. 줄 서기는 '기다릴 마음 + 시간'으로 나눈다."},{"id":"L14:4","text":"그리고 자발적으로 가격을 지불하려는 마음이, 자발적으로 줄을 서서 기다리려는 마음보다 더 나은 가치 평가 기준이라고 추정할 근거는 없다.","paragraph":0,"memberIds":["L14:4"],"topic":"그리고 '돈을 내겠다는 마음'이 '기다리겠다는 마음'보다 더 좋은 기준이라고 볼 이유는 없다."}]}]},"editorSourceVersion":"97de231476ff988c55e8a087413e585f17b9dd7f2915c7cb3a23110e900bfc61"}]},{"name":"U22-46-B2 · 비교","items":[{"paragraphCount":2,"readingLabel":"14문단 · 새 예시 적용","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 14문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 14문단]\n암표 거래를 옹호하는 사람들은 줄 서기가 시간이 남아도는 사람들에게 유리한 차별이라고 비판한다. 맞는 말이지만, 시장이 돈 많은 사람들을 유리하게 차별한다는 말과 같은 맥락에서만 그러하다. 시장이 자발적으로 돈을 지불하려는 마음과 능력을 바탕으로 재화를 분배하듯, 줄 서기는 자발적으로 기다리려는 마음과 능력을 바탕으로 재화를 분배한다. 그리고 자발적으로 가격을 지불하려는 마음이, 자발적으로 줄을 서서 기다리려는 마음보다 더 나은 가치 평가 기준이라고 추정할 근거는 없다.\n\n[새 적용 예시 · 원문 사례 아님]\n학급에서 유니폼을 나눌 방법으로 최고가 경매와 먼저 와서 기다린 사람에게 주는 선착순을 비교한다. 학생마다 가진 돈과 기다릴 수 있는 시간은 다르다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"originPage":"unit22","skills":["비교"],"id":"U22-46-B2","type":"ox","highlightEvidence":true,"ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","changed":"경매는 돈 많은 사람에게 유리하므로 선착순은 누구에게나 완벽하게 공정하다.","answer":"X","why":"경매는 돈 많은 사람에게 유리하며 선착순도 시간 많은 사람에게 유리할 수 있다.\n돈이 많으면 경매에서 높은 값을 부르기 쉬워요. 시간이 많으면 줄을 오래 서기 쉬워요. 경매에 문제가 있다고 해서 선착순에 아무 문제가 없는 것은 아니에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 14문단의 내용과 비교해 보세요.","claimEdits":[{"start":14,"end":41,"before":"유리하므로 선착순은 누구에게나 완벽하게 공정하다.","after":"유리하며 선착순도 시간 많은 사람에게 유리할 수 있다."}],"evidence":{"title":"웹 적용 · 경매와 선착순","statement":"경매는 돈 많은 사람에게 유리하다. 선착순도 기다릴 시간이 많은 사람에게 유리할 수 있다. 선착순이 완벽한 기준은 아니다.","explanation":"돈이 많으면 경매에서 높은 값을 부르기 쉬워요. 시간이 많으면 줄을 오래 서기 쉬워요. 경매에 문제가 있다고 해서 선착순에 아무 문제가 없는 것은 아니에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 14문단의 내용과 비교해 보세요.","valid":["L14:2"],"sources":[{"id":"L14","title":"줄 서기를 돈으로 살 수 있을까","label":"14문단","sentences":[{"id":"L14:1","text":"암표 거래를 옹호하는 사람들은 줄 서기가 시간이 남아도는 사람들에게 유리한 차별이라고 비판한다.","paragraph":0,"memberIds":["L14:1"],"topic":"암표 거래를 옹호하는 사람들은 “줄 서기도 시간이 많은 사람에게 유리한 차별이다”라고 비판한다."},{"id":"L14:2","text":"맞는 말이지만, 시장이 돈 많은 사람들을 유리하게 차별한다는 말과 같은 맥락에서만 그러하다.","paragraph":0,"memberIds":["L14:2"],"topic":"필자는 그 지적을 인정한다. 다만 시장도 돈 많은 사람에게 유리하므로, 줄 서기에만 있는 문제는 아니라고 말한다."},{"id":"L14:3","text":"시장이 자발적으로 돈을 지불하려는 마음과 능력을 바탕으로 재화를 분배하듯, 줄 서기는 자발적으로 기다리려는 마음과 능력을 바탕으로 재화를 분배한다.","paragraph":0,"memberIds":["L14:3"],"topic":"시장은 '돈 낼 마음 + 돈'으로 나눈다. 줄 서기는 '기다릴 마음 + 시간'으로 나눈다."},{"id":"L14:4","text":"그리고 자발적으로 가격을 지불하려는 마음이, 자발적으로 줄을 서서 기다리려는 마음보다 더 나은 가치 평가 기준이라고 추정할 근거는 없다.","paragraph":0,"memberIds":["L14:4"],"topic":"그리고 '돈을 내겠다는 마음'이 '기다리겠다는 마음'보다 더 좋은 기준이라고 볼 이유는 없다."}]}]},"editorSourceVersion":"d39834810b950e1b601b46f0ad3d0fce47b868a63977c893a902d30f353b9051"}]},{"name":"U22-E03-B1 · 비교","items":[{"id":"U22-E03-B1","type":"ox","answer":"O","changed":"시장을 지지하는 사람들은 다온이 책을 가장 소중히 여긴다고 본다. 세 사람 중 가장 많은 8천 원을 내겠다고 했기 때문이다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","why":"시장을 지지하는 사람들은 돈을 얼마까지 내겠다는지로 책을 얼마나 원하는지 판단해요. 이 기준으로 보면 가장 많은 돈을 내겠다는 다온이 책을 가장 원한다고 보겠지요.","paragraphCount":2,"readingLabel":"6문단 · 쉬운 예시","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 6문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 6문단]\n이렇게 시장 거래의 결과로 구매자와 판매자는 모두 행복해지고 효용은 증가한다. 이것이 바로 자유 시장이 재화를 효율적으로 분배한다고 주장하는 경제학자들의 입장이다. 시장은 사람들이 상호 유리한 방향으로 거래하는 것을 허용함으로써, 재화에 가장 높은 가치를 매기는 사람에게 그 재화를 할당한다. 그리고 그 기준은 얼마나 지불할 의사가 있느냐로 측정한다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n같은 책 한 권을 원하는 세 사람이 있다. 가람은 2천 원, 나래는 5천 원, 다온은 8천 원까지 낼 의사가 있다고 말했다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","examplePractice":true,"skills":["비교"],"evidence":{"title":"가치를 재는 시장의 기준","statement":"시장을 지지하는 사람들은 다온이 책을 가장 소중히 여긴다고 본다. 세 사람 중 가장 많은 8천 원을 내겠다고 했기 때문이다.","explanation":"시장을 지지하는 사람들은 돈을 얼마까지 내겠다는지로 책을 얼마나 원하는지 판단해요. 이 기준으로 보면 가장 많은 돈을 내겠다는 다온이 책을 가장 원한다고 보겠지요.","valid":["L06:3","L06:4"],"sources":[{"id":"L06","title":"줄 서기를 돈으로 살 수 있을까","label":"6문단","sentences":[{"id":"L06:1","text":"이렇게 시장 거래의 결과로 구매자와 판매자는 모두 행복해지고 효용은 증가한다.","paragraph":0,"memberIds":["L06:1"],"topic":"정리하면, 거래 덕분에 사는 사람도 파는 사람도 행복해지고 만족(효용)이 커진다."},{"id":"L06:2","text":"이것이 바로 자유 시장이 재화를 효율적으로 분배한다고 주장하는 경제학자들의 입장이다.","paragraph":0,"memberIds":["L06:2"],"topic":"그래서 경제학자들은 \"시장에 맡기면 물건(재화)이 낭비 없이 가장 알맞게(효율적으로) 나뉜다.\"라고 말한다."},{"id":"L06:3","text":"시장은 사람들이 상호 유리한 방향으로 거래하는 것을 허용함으로써, 재화에 가장 높은 가치를 매기는 사람에게 그 재화를 할당한다.","paragraph":0,"memberIds":["L06:3"],"topic":"시장에서는 서로 이득이 되는 거래를 자유롭게 할 수 있다. 그러면 물건은 그 물건을 가장 귀하게 여기는 사람에게 간다."},{"id":"L06:4","text":"그리고 그 기준은 얼마나 지불할 의사가 있느냐로 측정한다.","paragraph":0,"memberIds":["L06:4"],"topic":"그런데 '누가 가장 귀하게 여기는지'는 '누가 돈을 가장 많이 낼 마음이 있는지'로 잰다."}]}]},"editorSourceVersion":"19f661b87d510679e65c9dada94d305e2b53410a644ff920754a94156dd1d6d3"}]},{"name":"U22-E03-B2 · 비교","items":[{"id":"U22-E03-B2","type":"ox","answer":"X","changed":"시장을 지지하는 사람들은 2천 원을 내겠다는 가람이 책을 가장 소중히 여긴다고 본다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","why":"시장을 지지하는 사람들은 돈을 얼마까지 내겠다는지로 책을 얼마나 원하는지 판단해요. 이 기준으로 보면 가장 많은 돈을 내겠다는 다온이 책을 가장 원한다고 보겠지요.","paragraphCount":2,"readingLabel":"6문단 · 쉬운 예시","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 6문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 6문단]\n이렇게 시장 거래의 결과로 구매자와 판매자는 모두 행복해지고 효용은 증가한다. 이것이 바로 자유 시장이 재화를 효율적으로 분배한다고 주장하는 경제학자들의 입장이다. 시장은 사람들이 상호 유리한 방향으로 거래하는 것을 허용함으로써, 재화에 가장 높은 가치를 매기는 사람에게 그 재화를 할당한다. 그리고 그 기준은 얼마나 지불할 의사가 있느냐로 측정한다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n같은 책 한 권을 원하는 세 사람이 있다. 가람은 2천 원, 나래는 5천 원, 다온은 8천 원까지 낼 의사가 있다고 말했다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","examplePractice":true,"skills":["비교"],"evidence":{"title":"가치를 재는 시장의 기준","statement":"시장을 지지하는 사람들은 8천 원을 내겠다는 다온이 책을 가장 소중히 여긴다고 본다.","explanation":"시장을 지지하는 사람들은 돈을 얼마까지 내겠다는지로 책을 얼마나 원하는지 판단해요. 이 기준으로 보면 가장 많은 돈을 내겠다는 다온이 책을 가장 원한다고 보겠지요.","valid":["L06:3","L06:4"],"sources":[{"id":"L06","title":"줄 서기를 돈으로 살 수 있을까","label":"6문단","sentences":[{"id":"L06:1","text":"이렇게 시장 거래의 결과로 구매자와 판매자는 모두 행복해지고 효용은 증가한다.","paragraph":0,"memberIds":["L06:1"],"topic":"정리하면, 거래 덕분에 사는 사람도 파는 사람도 행복해지고 만족(효용)이 커진다."},{"id":"L06:2","text":"이것이 바로 자유 시장이 재화를 효율적으로 분배한다고 주장하는 경제학자들의 입장이다.","paragraph":0,"memberIds":["L06:2"],"topic":"그래서 경제학자들은 \"시장에 맡기면 물건(재화)이 낭비 없이 가장 알맞게(효율적으로) 나뉜다.\"라고 말한다."},{"id":"L06:3","text":"시장은 사람들이 상호 유리한 방향으로 거래하는 것을 허용함으로써, 재화에 가장 높은 가치를 매기는 사람에게 그 재화를 할당한다.","paragraph":0,"memberIds":["L06:3"],"topic":"시장에서는 서로 이득이 되는 거래를 자유롭게 할 수 있다. 그러면 물건은 그 물건을 가장 귀하게 여기는 사람에게 간다."},{"id":"L06:4","text":"그리고 그 기준은 얼마나 지불할 의사가 있느냐로 측정한다.","paragraph":0,"memberIds":["L06:4"],"topic":"그런데 '누가 가장 귀하게 여기는지'는 '누가 돈을 가장 많이 낼 마음이 있는지'로 잰다."}]}]},"claimEdits":[{"start":14,"end":17,"before":"2천 ","after":"8천 "},{"start":25,"end":29,"before":"가람이 ","after":"다온이 "}],"editorSourceVersion":"809acbc76771498e7e61b7017cf7290c2d6a11603c481ab8f86a1671fcaec494"}]}]};})(window);
